insert into public.competency_prerequisites (competency_id, prerequisite_competency_id) select c.id,p.id from public.competencies c join public.competencies p on p.code in ('R1','R2','R3') where c.code='R4' on conflict do nothing; insert into public.competency_prerequisites (competency_id, prerequisite_competency_id) select c.id,p.id from public.competencies c join public.competencies p on p.code='R4' where c.code='R5' on conflict do nothing; insert into public.competency_prerequisites (competency_id, prerequisite_competency_id) select c.id,p.id from public.competencies c join public.competencies p on p.code='R5' where c.code in ('R6','R7') on conflict do nothing; insert into public.competency_prerequisites (competency_id, prerequisite_competency_id) select c.id,p.id from public.competencies c join public.competencies p on p.code in ('R6','R7') where c.code='R8' on conflict do nothing;;
